  let SPLONGT=0,SPMOVED=0,IS_PREVIEW=0,TALKING=0,CUEON=0,CC0ON=0;
  /* v3.3：语音包只留接口，默认关；音效与背景音一律本地合成（见「声与色」卡） */
  /* v2.4：待机微表演调度（固定散列）与横屏手动标记 */
  let IDLET=0,IDLEKEY='',IDLESTEP=0,LAND_MANUAL=0;
