    h+='<div class="card"><div class="tagline">表 演 全 册 · '+(PF?PF.total:0)+' 层</div>'
      +(PF?'<div class="mini">表演覆盖 <b>'+PF.reachable+'/'+PF.total
        +'</b> 层可达 · 专属钩子 '+PF.owned+' / 轮播补位 '+PF.pool
        +' · '+PF.scenes+' 关全部可轮播命中（原仅 '+PF.sceneHookKeys
        +' 关可达，补 '+PF.sceneGapBefore+' 关）。</div>':'')
      +(PF&&PF.plan?'<div class="mini">'+esc(PF.plan.title)+' 已补 <b>'
        +PF.plan.produced+'/'+PF.plan.totalItems+'</b> 张 · <b>还差 '
        +PF.plan.remaining+' 轮</b>全部补完（'+PF.plan.totalRounds+' 轮 × '
        +PF.plan.perRound+' 张，清单封闭不追加第 13 轮）。</div>':'')
      +'<div class="mini">12 域折叠，点开任意层即预演一拍；按情境换层，不是逐帧动画。</div>'
      +'<div class="viewsel"><button data-perf-toggle="1" class="'+(PERFOPEN?'on':'')
      +'">'+(PERFOPEN?'收起全册':'展开全册')+'</button></div>'
      +(PERFOPEN?'<div class="viewsel" style="margin-top:6px;flex-wrap:wrap">'
        +PDS.map(d=>'<button data-perf-domain="'+esc(d.key)+'" class="'
          +(PERFDOM===d.key?'on':'')+'">'+esc(d.name)+'</button>').join('')
        +'</div>':'')
      +(PERFOPEN&&PERFDOM?'<div class="mini" style="margin-top:6px">'
        +esc((PDS.filter(d=>d.key===PERFDOM)[0]||{}).name||'')+' · '+PDL.length+' 层</div>'
        +'<div class="viewsel" style="margin-top:4px;flex-wrap:wrap">'
        +PDL.map(k=>'<button data-pose-pick="'+esc(k)+'">'
          +esc(PFL[k]||k)+'</button>').join('')
        +'</div>':'')
