    /* ===== v1.9 场 景 · 预 览 可 选 ===== */
    const BDL=SG&&SG.backdropList?SG.backdropList(S):[];
    const curBD=BDL.filter(x=>x.current)[0];
    h+='<div class="card"><div class="tagline">场 景 · 预 览 可 选</div>'
