    /* ===== v2.2 向 导 人 声 · 声 线 与 表 演 ===== */
    const VPX=W.a11y,VP=(VPX&&VPX.voicePacks)||[],curVP=VPX&&VPX.status?VPX.status().voicePack:'gentle';
    h+='<div class="card"><div class="tagline">向 导 人 声 · 声 线 与 表 演</div>'
