      +'<div class="scene-host"></div></details>'
      +(doneRows?'<details class="scenedone"><summary>已通关 '
        +PERFORMED.filter(k=>scn.some(x=>x.key===k)).length+' 关 · 点开看</summary>'
        +doneRows+'</details>':'')
      +'</div>';

    /* ===== v3.1 CC0 真人语音包 · 来源与开关 ===== */
    const CC=(D.character&&D.character.voicePack)||{},NT=CC.notice||{};
    h+='<div class="card"><div class="tagline">向 导 语 音 包 · 接口保留 · 默认关</div>'
