      +'</div>';

    /* ===== v1.5 人 声 · 角 色 音 色 ===== */
    h+='<div class="card"><div class="tagline">人 声 · 角 色 音 色</div>'
      +'<div class="mini">'+esc((sg.voicePack&&sg.voicePack.honest)||'')+'</div>'
